import{_ as e,o as i,c as s,ag as n}from"./chunks/framework.CrXGS008.js";const h=JSON.parse('{"title":"Pierwsze kroki","description":"","frontmatter":{},"headers":[],"relativePath":"pl/getting-started.md","filePath":"pl/getting-started.md"}'),o={name:"pl/getting-started.md"};function r(t,a,p,l,d,c){return i(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="pierwsze-kroki" tabindex="-1">Pierwsze kroki <a class="header-anchor" href="#pierwsze-kroki" aria-label="Permalink to &quot;Pierwsze kroki&quot;">​</a></h1><p>Ta strona prowadzi od zakupu do pierwszego otwarcia panelu ustawień w grze. Wygląda tak samo dla każdego skryptu Nayretis.</p><h2 id="zakup-i-pobranie" tabindex="-1">Zakup i pobranie <a class="header-anchor" href="#zakup-i-pobranie" aria-label="Permalink to &quot;Zakup i pobranie&quot;">​</a></h2><ol><li>Kup skrypt w <a href="https://www.nayretis.com" target="_blank" rel="noreferrer">sklepie Nayretis</a>. Płatność obsługuje Tebex.</li><li>Zaloguj się do <a href="https://portal.cfx.re" target="_blank" rel="noreferrer">Portal</a> kontem Cfx.re użytym przy zakupie. Skrypt i <code>nay_lib</code> znajdziesz w przyznanych zasobach (granted assets).</li><li>Pobierz oba. <code>nay_lib</code> jest dołączany do każdego skryptu Nayretis i nigdy nie jest sprzedawany osobno.</li></ol><p>Skrypty są chronione przez Cfx escrow: uruchamiają się tylko na serwerze, którego klucz licencyjny należy do konta Cfx.re będącego ich właścicielem.</p><h2 id="wymagania" tabindex="-1">Wymagania <a class="header-anchor" href="#wymagania" aria-label="Permalink to &quot;Wymagania&quot;">​</a></h2><ul><li><a href="https://github.com/overextended/oxmysql" target="_blank" rel="noreferrer">oxmysql</a>, uruchomiony i połączony z bazą danych.</li><li>Jeden z obsługiwanych frameworków: ESX Legacy, QBCore, QBox lub ox_core. Ekwipunki, targety i powiadomienia opisuje strona <a href="/pl/bridge/">Bridge</a>.</li></ul><h2 id="instalacja" tabindex="-1">Instalacja <a class="header-anchor" href="#instalacja" aria-label="Permalink to &quot;Instalacja&quot;">​</a></h2><p>Skopiuj folder <code>nay_lib</code> i folder skryptu do folderu <code>resources</code>. W <code>server.cfg</code> uruchom je po zasobach frameworka, ekwipunku i targetu:</p><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ensure oxmysql</span></span>
<span class="line"><span># your framework, inventory and target resources here</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ensure nay_lib</span></span>
<span class="line"><span>ensure nay_car_wash</span></span></code></pre></div><p><code>nay_lib</code> instaluje się raz, bez względu na liczbę używanych skryptów Nayretis. Uruchamiaj go przed każdym skryptem Nayretis.</p><h2 id="pierwsze-uruchomienie" tabindex="-1">Pierwsze uruchomienie <a class="header-anchor" href="#pierwsze-uruchomienie" aria-label="Permalink to &quot;Pierwsze uruchomienie&quot;">​</a></h2><p>Uruchom serwer. Tabele w bazie danych tworzą się automatycznie, nie trzeba importować żadnego pliku SQL. W konsoli powinno pojawić się:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[script:nay_lib] [INFO] Bridge ready: framework=qbox inventory=ox_inventory</span></span>
<span class="line"><span>[script:nay_lib] [INFO] Ready: settings, permissions and migrations loaded</span></span></code></pre></div><p>Nazwy frameworka i ekwipunku odpowiadają temu, czego używa Twój serwer.</p><h2 id="nadaj-sobie-dostep" tabindex="-1">Nadaj sobie dostęp <a class="header-anchor" href="#nadaj-sobie-dostep" aria-label="Permalink to &quot;Nadaj sobie dostęp&quot;">​</a></h2><p>Ustawienia edytuje się w grze komendą <code>/nay</code>. Nadaj grupie admin pełny dostęp w <code>server.cfg</code>:</p><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>add_ace group.admin nay.admin allow</span></span></code></pre></div><p>Albo nadaj go jednemu graczowi z konsoli serwera:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nay_grant license &lt;license&gt; nay.admin</span></span></code></pre></div><p>Następnie wejdź na serwer i wpisz <code>/nay</code>. Więcej możliwości opisuje strona <a href="/pl/nay-lib/permissions">Uprawnienia</a>.</p><h2 id="co-dalej" tabindex="-1">Co dalej <a class="header-anchor" href="#co-dalej" aria-label="Permalink to &quot;Co dalej&quot;">​</a></h2><ul><li>Poznaj <a href="/pl/nay-lib/panel">panel /nay</a>: języki, motyw, uprawnienia, API i webhooki.</li><li>Skonfiguruj <a href="/pl/car-wash/">Car Wash</a>.</li><li>Coś się nie uruchamia? Przeczytaj <a href="/pl/faq">FAQ</a>.</li></ul>`,23)])])}const y=e(o,[["render",r]]);export{h as __pageData,y as default};
